## Bridging Option and Result

In real code, you'll use both Option and Result. Sometimes one function returns Option but you need Result. Converting is straightforward.

### Option → Result

```xiom
fn opt_to_res(opt: Option[Int], err_msg: Str) -> Result[Int, Str] {
  return match opt {
    Some(val) => Ok(val),
    None => Err(err_msg),
  };
}

fn main() -> Int {
  let found = Some(42);
  let not_found: Option[Int] = None;

  let r1 = opt_to_res(found, "Value missing");
  let r2 = opt_to_res(not_found, "Value missing");

  io.println(r1.unwrap_or(0));  // 42
  io.println(r2.unwrap_or(0));  // 0 (error suppressed)
  return 0;
}
```

### Result → Option (Dropping Error Info)

```xiom
fn res_to_opt(res: Result[Int, Str]) -> Option[Int] {
  return match res {
    Ok(val) => Some(val),
    Err(_) => None,
  };
}

fn main() -> Int {
  let success: Result[Int, Str] = Ok(99);
  let failure: Result[Int, Str] = Err("Network error");

  let o1 = res_to_opt(success);
  let o2 = res_to_opt(failure);

  io.println(o1.unwrap_or(0));  // 99
  io.println(o2.unwrap_or(0));  // 0 (error info lost)
  return 0;
}
```

### Converting Both Ways in a Pipeline

```xiom
fn find_user(id: Int) -> Option[Str] {
  if id == 1 { return Some("Alice"); }
  if id == 2 { return Some("Bob"); }
  return None;
}

fn get_user_or_error(id: Int) -> Result[Str, Str] {
  let user_opt = find_user(id);
  return match user_opt {
    Some(name) => Ok(name),
    None => Err("User " + string.int_to_str(id) + " not found"),
  };
}

fn main() -> Int {
  match get_user_or_error(1) {
    Ok(name) => io.println("Hello, " + name),
    Err(e) => io.println(e),
  };
  match get_user_or_error(99) {
    Ok(name) => io.println("Hello, " + name),
    Err(e) => io.println(e),
  };
  return 0;
}
```

