use xiom.io;

use xiom.string;
fn find_student(id: Int) -> Option[Str] {
  if id == 1 { return Some("Alex"); }
  if id == 2 { return Some("Bailey"); }
  if id == 3 { return Some("Casey"); }
  return None;
}

fn get_student(id: Int) -> Result[Str, Str] {
  let maybe = find_student(id);
  return match maybe {
    Some(name) => Ok(name),
    None => Err("Student ID " + to_string(id) + " not found"),
  };
}

fn check_cache(key: Int) -> Result[Int, Str] {
  if key == 100 { return Ok(42); }
  if key == 200 { return Ok(99); }
  return Err("Cache miss");
}

fn cache_to_opt(res: Result[Int, Str]) -> Option[Int] {
  return match res {
    Ok(val) => Some(val),
    Err(_) => None,
  };
}

fn main() -> Int {
  io.println(get_student(2).unwrap_or("Not found").to_str());
  io.println(get_student(99).unwrap_or("Not found").to_str());
  io.println(cache_to_opt(check_cache(100)).unwrap_or(0).to_str());
  io.println(cache_to_opt(check_cache(999)).unwrap_or(0).to_str());
  return 0;
}
